insert:
onPlayTitleChanged:
{
labelTitle.setMainText(playTitle)
}
onArtistNameChanged:
{
labelArtist.setMainText(artistName)
}
onAlbumNameChanged:
{
labelAlbum.setMainText(albumName)
}
function resetScrubBarValue()
{
scrub.resetValue()
}
SCmnMarquee {
id: labelTitle
width: p.labelTitleWidth
height: p.labelTitleHeight
anchors{top: scrubBar.bottom; topMargin: p.marginTitleTop;
horizontalCenter: base.horizontalCenter; }
pixelSize: p.pixelSizeTitle
fontWeight: p.fontLight
fontColor: p.fontColorL1
isUseMarquee: base.isTitleMarquee
left_mask_image_path: "qrc:/ic_audio_play_track_name_area_mask_left.png"
right_mask_image_path: "qrc:/ic_audio_play_track_name_area_mask_right.png"
}
SCmnMarquee {
id: labelArtist
width: p.labelArtistWidth
height: p.labelArtistHeight
anchors {top: labelTitle.bottom; topMargin: p.marginArtistTop;
horizontalCenter: base.horizontalCenter}
pixelSize: p.pixelSizeL
fontWeight: p.fontRegular
fontColor: p.fontColorL2
isUseMarquee: false
right_mask_image_path: "qrc:/ic_audio_play_artist_area_mask_right.png"
}
SCmnMarquee {
id: labelAlbum
visible: !base.compactMetadata
width: p.labelAlbumWidth
height: p.labelAlbumHeight
anchors{top: labelArtist.bottom;
horizontalCenter: base.horizontalCenter}
pixelSize: p.pixelSizeL
fontWeight: p.fontRegular
fontColor: p.fontColorL2
isUseMarquee: false
left_mask_image_path: "qrc:/ic_audio_play_album_area_mask_left.png"
right_mask_image_path: "qrc:/ic_audio_play_album_area_mask_right.png"
}
Item {
id: scrubBar
width: p.scrubBarWidth
height: p.scrubBarHeight
anchors{top: base.top; topMargin: p.scrubBarTopMargin
horizontalCenter: base.horizontalCenter}
ScrubBar {
id: scrub
labelToTrackGap: base.compactMetadata ? 12 : 4
width: parent.width
anchors{left: parent.left; bottom: parent.bottom}
barHeight: 50
totalPlaybackTime: base.totalPlaybackTime
currentlyPlayingTime: base.currentlyPlayingTime
totalPlayTrackNum: base.totalPlayTrackNum
currentryPlayTrackNum: base.currentryPlayTrackNum
labelTimeWidth: p.scrubBarLabelTimeWidth
fontWeightTime: p.fontRegular
fontWeightNo: p.fontRegular
fontColorTime: p.fontColorL2
fontColorTrackNo: p.fontColorL3
onPressed: base.pressed()
onReleased: base.released(time)
onPlayEnded: base.playEnded()
onReqSwipe: base.swipeSelector.reqSwipe()
}
}
onSwipeSelectorChanged: {
if( swipeSelector ) {
base.swipeSelector.anchors.fill = scrubBar
base.swipeSelector.target = scrubBar
}
}
Image {
id: lyricsImage
visible: base.lyrics_status === 2 ? true : false
anchors {right: base.compactMetadata ? labelArtist.left : labelAlbum.left; top: base.compactMetadata ? labelArtist.top : labelAlbum.top}
source: "qrc:/assets/images/ic_audio_play_lyrics_mark.png"
}
Image {
id: hiResIcon
visible: base.modeHiRes
anchors{left: base.compactMetadata ? labelArtist.right : labelAlbum.right; top: base.compactMetadata ? labelArtist.top : labelAlbum.top}
source: "qrc:/ic_audio_play_hr_mark.png"
}
}
